<script>
  // Payment card selector visual toggle
  const paymentCards = document.querySelectorAll('.payment-card');
  paymentCards.forEach(card => {
    card.addEventListener('click', () => {
      paymentCards.forEach(c => {
        c.classList.remove('bg-surface-container');
        c.classList.add('bg-surface-container-low');
      });
      card.classList.remove('bg-surface-container-low');
      card.classList.add('bg-surface-container');
      const radio = card.querySelector('input[type="radio"]');
      if (radio) radio.checked = true;
    });
  });

  // Collapsible Order summary drawer
  const summaryToggle = document.getElementById('order-summary-toggle');
  const summaryItems = document.getElementById('order-summary-items');
  const summaryChevron = document.getElementById('summary-chevron');
  let isOpen = true;

  summaryToggle.addEventListener('click', () => {
    isOpen = !isOpen;
    if (isOpen) {
      summaryItems.classList.remove('hidden');
      summaryChevron.style.transform = 'rotate(0deg)';
    } else {
      summaryItems.classList.add('hidden');
      summaryChevron.style.transform = 'rotate(180deg)';
    }
  });

  // Modal celebration toggle
  const placeOrderBtn = document.getElementById('place-order-btn');
  const successModal = document.getElementById('success-modal');
  const closeModalBtn = document.getElementById('close-modal-btn');

  placeOrderBtn.addEventListener('click', () => {
    successModal.classList.remove('hidden');
  });

  closeModalBtn.addEventListener('click', () => {
    successModal.classList.add('hidden');
  });
</script></main><aside class="fixed bottom-24 right-4 z-40 pointer-events-auto"><a class="flex items-center gap-2 bg-[#25D366] text-white px-4 py-2.5 rounded-full shadow-[0_8px_24px_-2px_rgba(37,211,102,0.35)] hover:bg-[#20ba59] active:scale-95 transition-all duration-200" href="https://wa.me/" rel="noopener noreferrer" target="_blank"><span class="material-symbols-outlined text-[20px]">chat</span><span class="font-body-md text-body-md font-semibold tracking-normal text-white">Order on WhatsApp</span><span class="material-symbols-outlined text-[16px]">arrow_forward_ios</span></a></aside><nav class="fixed bottom-0 w-full z-50 pb-safe bg-surface/90 backdrop-blur-xl shadow-[0_-2px_12px_rgba(24,39,63,0.05)]" data-active-classes="text-primary font-bold"><div class="flex justify-around items-center h-16 px-2"><a class="flex flex-col items-center justify-center gap-0.5 w-16 h-12 text-on-surface-variant hover:text-primary transition-colors duration-150" data-path="home" href="#"><span class="material-symbols-outlined text-[22px]">home</span><span class="font-label-caps text-label-caps tracking-normal capitalize">Home</span></a><a class="flex flex-col items-center justify-center gap-0.5 w-16 h-12 text-on-surface-variant hover:text-primary transition-colors duration-150" data-path="shop-catalog" href="#"><span class="material-symbols-outlined text-[22px]">styler</span><span class="font-label-caps text-label-caps tracking-normal capitalize">Catalog</span></a><a class="flex flex-col items-center justify-center gap-0.5 w-16 h-12 text-on-surface-variant hover:text-primary transition-colors duration-150" data-path="collections" href="#"><span class="material-symbols-outlined text-[22px]">auto_awesome_mosaic</span><span class="font-label-caps text-label-caps tracking-normal capitalize">Collections</span></a><a class="flex flex-col items-center justify-center gap-0.5 w-16 h-12 text-on-surface-variant hover:text-primary transition-colors duration-150" data-path="sizing-guide" href="#